<?php
// ============================================================
// Manager Purchase Requests — public/manager_purchase_requests.php
// Flow: Staff Stock Request → Manager encodes Qty+Remarks → Forward to Admin
// ============================================================
$page_id = 'mgr_purchase_requests';
require_once __DIR__ . '/../backend/lib.php';
require_once __DIR__ . '/db_connect.php';
require_login();  $me  = current_user();
$station_id = user_station_id();
$role  = role_key($me['role'] ?? '');  if (!in_array($role, ['manager', 'admin', 'superadmin'])) {  $_SESSION['error'] = 'Access denied. Manager access required.';  header('Location: dashboard.php'); exit;
}  // ── Ensure fuel_stock_requests table exists ──────────────────────────────────
try {  $pdo->exec("CREATE TABLE IF NOT EXISTS fuel_stock_requests (  id INT AUTO_INCREMENT PRIMARY KEY,  staff_id INT NOT NULL, station_id INT NOT NULL,  fuel_type VARCHAR(100) NOT NULL,  current_level DECIMAL(12,2) NOT NULL DEFAULT 0,  capacity DECIMAL(12,2) NOT NULL DEFAULT 0,  stock_status VARCHAR(30) NOT NULL DEFAULT 'LOW',  requested_liters DECIMAL(12,2) NOT NULL,  remarks TEXT,  status ENUM('Pending','Approved','Rejected') DEFAULT 'Pending',  approved_liters DECIMAL(12,2) NULL,  manager_id INT NULL, manager_notes TEXT NULL,  processed_at TIMESTAMP NULL,  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP  ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");  $pdo->exec("CREATE TABLE IF NOT EXISTS fuel_stock_request_audit (  id INT AUTO_INCREMENT PRIMARY KEY,  request_id INT NOT NULL,  action_type VARCHAR(50) NOT NULL,  performed_by INT NOT NULL,  performed_by_role VARCHAR(50) NOT NULL,  old_status VARCHAR(30) NULL, new_status VARCHAR(30) NULL,  notes TEXT,  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP  ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
} catch (Exception $ignored) {}  // ── Handle Merchandise Stock Request: Approve → Forward to Admin ─────────────
// This is handled via AJAX in backend/api/stock_request.php (action=approve)
// The approve action now sets status='Forwarded to Admin' and generates a PR ID  // ── Handle Fuel Stock Request POST ──────────────────────────────────────────
if ($_SERVER['REQUEST_METHOD'] === 'POST' && ($_POST['form_type'] ?? '') === 'fuel') {  $action = $_POST['action'] ?? '';  $req_id = (int)($_POST['request_id'] ?? 0);  if ($action === 'approve' && $req_id > 0) {  $approved_liters = (float)($_POST['approved_liters'] ?? 0);  $manager_notes  = trim($_POST['manager_notes'] ?? '');  if ($approved_liters > 0) {  try {  $stmt = $pdo->prepare("SELECT * FROM fuel_stock_requests WHERE id = ? AND station_id = ?");  $stmt->execute([$req_id, $station_id]);  $req = $stmt->fetch(PDO::FETCH_ASSOC);  if ($req && strtolower($req['status']) === 'pending') {  $pdo->beginTransaction();  $pdo->prepare("UPDATE fuel_stock_requests SET status='Approved', approved_liters=?, manager_id=?, manager_notes=?, processed_at=NOW(), updated_at=NOW() WHERE id=?")  ->execute([$approved_liters, $me['id'], $manager_notes, $req_id]);  $note = "Approved: {$req['requested_liters']} L → {$approved_liters} L of {$req['fuel_type']}. Manager: {$me['name']}.";  if ($manager_notes) $note .= " Notes: {$manager_notes}";  $pdo->prepare("INSERT INTO fuel_stock_request_audit (request_id, action_type, performed_by, performed_by_role, old_status, new_status, notes) VALUES (?, 'Approved', ?, ?, 'Pending', 'Approved', ?)")  ->execute([$req_id, $me['id'], $role, $note]);  $pdo->commit();  $_SESSION['success'] = "Fuel request approved. {$approved_liters} L of {$req['fuel_type']} confirmed.";  } else {  $_SESSION['error'] = 'Request not found or already processed.';  }  } catch (Exception $e) {  if ($pdo->inTransaction()) $pdo->rollBack();  $_SESSION['error'] = 'Error: ' . $e->getMessage();  }  } else {  $_SESSION['error'] = 'Approved liters must be greater than 0.';  }  } elseif ($action === 'reject' && $req_id > 0) {  $manager_notes = trim($_POST['manager_notes'] ?? '');  if (!empty($manager_notes)) {  try {  $stmt = $pdo->prepare("SELECT * FROM fuel_stock_requests WHERE id = ? AND station_id = ?");  $stmt->execute([$req_id, $station_id]);  $req = $stmt->fetch(PDO::FETCH_ASSOC);  if ($req && strtolower($req['status']) === 'pending') {  $pdo->beginTransaction();  $pdo->prepare("UPDATE fuel_stock_requests SET status='Rejected', manager_id=?, manager_notes=?, processed_at=NOW(), updated_at=NOW() WHERE id=?")  ->execute([$me['id'], $manager_notes, $req_id]);  $pdo->prepare("INSERT INTO fuel_stock_request_audit (request_id, action_type, performed_by, performed_by_role, old_status, new_status, notes) VALUES (?, 'Rejected', ?, ?, 'Pending', 'Rejected', ?)")  ->execute([$req_id, $me['id'], $role, "Rejected by {$me['name']}. Reason: {$manager_notes}"]);  $pdo->commit();  $_SESSION['success'] = 'Fuel request rejected successfully.';  } else {  $_SESSION['error'] = 'Request not found or already processed.';  }  } catch (Exception $e) {  if ($pdo->inTransaction()) $pdo->rollBack();  $_SESSION['error'] = 'Error: ' . $e->getMessage();  }  } else {  $_SESSION['error'] = 'Rejection reason is required.';  }  }  header('Location: manager_purchase_requests.php?tab=fuel');  exit;
}  // ── Fetch Fuel Requests ──────────────────────────────────────────────────────
$fuel_requests = [];
try {  $stmt = $pdo->prepare("  SELECT fsr.*, u.name AS staff_name, m.name AS manager_name  FROM fuel_stock_requests fsr  JOIN users u ON fsr.staff_id = u.id  LEFT JOIN users m ON fsr.manager_id = m.id  WHERE fsr.station_id = ?  ORDER BY CASE fsr.status WHEN 'Pending' THEN 1 WHEN 'Approved' THEN 2 WHEN 'Rejected' THEN 3 END, fsr.created_at DESC  ");  $stmt->execute([$station_id]);  $fuel_requests = $stmt->fetchAll(PDO::FETCH_ASSOC);
} catch (Exception $e) {}  $fuel_pending = count(array_filter($fuel_requests, fn($r) => $r['status'] === 'Pending'));  // ── Active tab ───────────────────────────────────────────────────────────────
$active_tab = $_GET['tab'] ?? 'merch';  $flash_success = $_SESSION['success'] ?? null; unset($_SESSION['success']);
$flash_error  = $_SESSION['error']  ?? null; unset($_SESSION['error']);  include __DIR__ . '/../partials/header.php';
?>  <style>
