><th>Processed On</th>  </tr>  </thead>  <tbody id="mHistoryBody">  <tr><td colspan="9" style="text-align:center;padding:30px;color:#6c757d;"><i class="fas fa-spinner fa-spin"></i> Loading...</td></tr>  </tbody>  </table>  </div>  </div>
