<div id="tab-fuel" style="display:<?php echo $active_tab === 'fuel' ? 'block' : 'none'; ?>;">  <div class="pr-summary">  <div class="pr-card">  <div class="pr-card-num"><?php echo count($fuel_requests); ?></div>  <div class="pr-card-lbl">Total</div>  </div>  <div class="pr-card pr-card-pending">  <div class="pr-card-num"><?php echo $fuel_pending; ?></div>  <div class="pr-card-lbl">Pending</div>  </div>  <div class="pr-card" style="">  <div class="pr-card-num" style="color:#155724;"><?php echo count(array_filter($fuel_requests, fn($r) => $r['status'] === 'Approved')); ?></div>  <div class="pr-card-lbl">Approved</div>  </div>  <div class="pr-card pr-card-rejected">  <div class="pr-card-num"><?php echo count(array_filter($fuel_requests, fn($r) => $r['status'] === 'Rejected')); ?></div>  <div class="pr-card-lbl">Rejected</div>  </div>  </div>  <div class="card" style="padding:0;">  <div class="pr-table-wrap">  <table class="pr-table">  <thead>  <tr>  <th>#</th><th>Date</th><th>Staff</th><th>Fuel Type</th>  <th>Current Level</th><th>Status</th><th>To Replenish</th>  <th>Approved (L)</th><th>Manager Notes</th><th>Action</th>  </tr>  </thead>  <tbody>  <?php foreach ($fuel_requests as $req):  $st  = $req['status'] ?? 'Pending';  $cls = 'pr-sbadge pr-sbadge-' . strtolower($st);  $stockClr = in_array($req['stock_status'] ?? '', ['OUT OF STOCK','CRITICAL']) ? '#dc3545' : '#dc3545';  ?>  <tr>  <td style="font-family:monospace;font-size:11px;color:#888;">#<?php echo $req['id']; ?></td>  <td style="font-size:12px;"><?php echo date('M d, Y H:i', strtotime($req['created_at'])); ?></td>  <td><?php echo htmlspecialchars($req['staff_name']); ?></td>  <td><strong><?php echo htmlspecialchars($req['fuel_type']); ?></strong></td>  <td>  <?php echo number_format($req['current_level'], 2); ?> L  <span style="color:<?php echo $stockClr; ?>;font-size:11px;font-weight:700;display:block;"><?php echo htmlspecialchars($req['stock_status'] ?? ''); ?></span>  </td>  <td><span class="<?php echo $cls; ?>"><?php echo htmlspecialchars($st); ?></span></td>  <td style="font-weight:700;text-align:center;"><?php echo number_format($req['requested_liters'], 2); ?></td>  <td style="text-align:center;">  <?php if ($req['approved_liters'] !== null): ?>  <strong style="color:#28a745;"><?php echo number_format($req['approved_liters'], 2); ?></strong>  <?php else: ?><span style="color:#adb5bd;">—</span><?php endif; ?>  </td>  <td style="font-size:12px;max-width:180px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;" title="<?php echo htmlspecialchars($req['manager_notes'] ?? ''); ?>">  <?php echo $req['manager_notes'] ? htmlspecialchars($req['manager_notes']) : '<span style="color:#adb5bd;">—</span>'; ?>  </td>  <td>  <?php if ($st === 'Pending'): ?>  <button class="pr-btn pr-btn-approve" onclick="openFuelApprove(<?php echo $req['id']; ?>, '<?php echo htmlspecialchars($req['fuel_type'], ENT_QUOTES); ?>', <?php echo $req['requested_liters']; ?>)">  <i class="fas fa-check"></i> Approve  </button>  <button class="pr-btn pr-btn-reject" onclick="openFuelReject(<?php echo $req['id']; ?>, '<?php echo htmlspecialchars($req['fuel_type'], ENT_QUOTES); ?>')">  <i class="fas fa-times"></i> Reject  </button>  <?php else: ?>  <span style="font-size:11px;color:#6c757d;">Processed</span>  <?php endif; ?>  </td>  </tr>  <?php endforeach; ?>  <?php if (empty($fuel_requests)): ?>  <tr><td colspan="10" style="text-align:center;padding:48px;color:#888;">  <i class="fas fa-gas-pump" style="font-size:36px;display:block;margin-bottom:12px;opacity:0.2;"></i>  No fuel stock requests yet.  </td></tr>  <?php endif; ?>  </tbody>  </table>  </div>  </div>
