button>  </div>  </form>  </div>
</div>  <div id="fuelRejectModal" class="pr-modal">  <div class="pr-modal-box" style="max-width:480px;">  <div class="pr-modal-header">  <div class="pr-modal-title"><i class="fas fa-times-circle" style="color:#dc3545;margin-right:7px;"></i> Reject Fuel Request</div>  <button class="pr-modal-close" onclick="closePrModal('fuelRejectModal')">&times;</button>  </div>  <form method="post">  <input type="hidden" name="form_type" value="fuel">  <input type="hidden" name="action" value="reject">  <input type="hidden" name="request_id" id="fuelRejectId">  <div style="background:#f8f9fa;border:1px solid #e9ecef;border-radius:8px;padding:12px;margin-bottom:14px;text-align:center;">  <div style="font-size:12px;color:#888;margin-bottom:6px;text-transform:uppercase;">Fuel Type</div>  <div style="font-weight:700;color:#212529;font-size:16px;" id="fuelRejectFuel">—</div>  </div>  <div style="margin-bottom:14px;">  <label style="display:block;font-weight:700;font-size:13px;margin-bottom:6px;">Rejection Reason <span style="color:red;">*</span></label>  <textarea name="manager_notes" rows="3" required placeholder="Explain why this request is rejected..." style="width:100%;padding:10px;border:1px solid #ced4da;border-radius:6px;resize:vertical;"></textarea>  </div>  <div class="pr-modal-footer">  <button type="submit" style="background:#dc3545;color:#fff;border:none;padding:10px 24px;border-radius:6px;font-weight:700;cursor:pointer;"><i class="fas fa-times"></i> Confirm Reject</button>  <button type="button" onclick="closePrModal('fuelRejectModal')" style="background:#6c757d;color:#fff;border:none;padding:10px 20px;border-radius:6px;cursor:pointer;">Cancel</button>  </div>  </form>  </div>
</div>  <!-- ════════════════════════════════════════════════════════════  MERCHANDISE APPROVE MODAL  ════════════════════════════════════════════════════════════ -->
<div class="pr-modal" id="mApproveModal">  <div class="pr-modal-box">  <div class="pr-modal-header">  <div class="pr-modal-title"><i class="fas fa-check-circle" style="color:#28a745;"></i> Approve &amp; Forward to Admin</div>  <button class="pr-modal-close" onclick="closePrModal('mApproveModal')">&times;</button>  </div>  <div class="field-grid2">  <div class="field-group2"><label>SKU</label><input type="text" id="mAppSku" readonly></div>  <div class="field-group2"><label>Product</label><input type="text" id="mAppName" readonly></div>  <div class="field-group2"><label>Category</label><input type="text" id="mAppCategory" readonly></div>  <div class="field-group2"><label>Requested By</label><input type="text" id="mAppStaff" readonly></div>  <div class="field-group2"><label>Current Stock</label><input type="text" id="mAppCurStock" readonly></div>  <div class="field-group2"><label>Stock Status</label><input type="text" id="mAppStockStatus" readonly></div>  </div>  <div class="field-grid2">  <div class="field-group2" style="grid-column:1/-1;">  <label>Approved Quantity <span style="color:#dc3545;">*</span></label>  <input type="number" id="mAppQty" min="1" required placeholder="Enter quantity to request from supplier..." style="font-size:16px;font-weight:700;color:#002F70;">  </div>  </div>  <div class="field-group2" style="margin-bottom:16px;">  <label>Remarks / Notes</label>  <textarea id="mAppNotes" rows="3" placeholder="Optional: special instructions, urgency, etc."></textarea>  </div>  <div class="info-box2">  <i class="fas fa-info-circle"></i> <strong>On Approve:</strong><br>  &bull; A <strong>Purchase Request ID</strong> will be auto-generated (PR-YYYYMMDD-XXXX)<br>  &bull; Status → <strong>Forwarded to Admin</strong><br>  &bull; Admin will receive this as a Purchase Order to finalize &amp; print<br>  &bull; Audit trail logged: Manager ID, qty, timestamp  </div>  <div id="mAppError" style="display:none;background:#fee2e2;color:#dc3545;padding:10px;border-radius:6px;margin-bottom:12px;font-size:13px;"></div>  <div class="pr-modal-footer">  <button type="button" onclick="closePrModal('mApproveModal')" style="padding:9px 22px;background:#6c757d;color:#fff;border:none;border-radius:6px;cursor:pointer;">Cancel</button>  <button type="button" id="mAppSubmitBtn" onclick="submitMerchApprove()" style="padding:9px 22px;background:#28a745;color:#fff;border:none;border-radius:6px;cursor:pointer;font-weight:600;">  <i class="fas fa-paper-plane"></i> Approve &amp; Forward to Admin  </button>  </div>  </div>
</div>  <div class="pr-modal" id="mRejectModal">  <div class="pr-modal-box" style="max-width:480px;">  <div class="pr-modal-header">  <div class="pr-modal-title"><i class="fas fa-times-circle" style="color:#dc3545;"></i> Reject Stock Request</div>  <button class="pr-modal-close" onclick="closePrModal('mRejectModal')">&times;</button>  </div>  <div class="field-group2" style="margin-bottom:8px;">  <label>Product</label>  <input type="text" id="mRejName" readonly style="width:100%;padding:9px;border:1px solid #dee2e6;border-radius:6px;background:#f8f9fa;color:#6c757d;">  </div>  <div class="field-group2" style="margin-bottom:16px;">  <label>Rejection Reason <span style="color:#dc3545;">*</span></label>  <textarea id="mRejNotes" rows="4" placeholder="Required: explain why this request is being rejected..." style="width:100%;padding:9px;border:1px solid #dee2e6;border-radius:6px;font-size:13px;resize:vertical;"></textarea>  </div>  <div id="mRejError" style="display:none;background:#fee2e2;color:#dc3545;padding:10px;border-radius:6px;margin-bottom:12px;font-size:13px;"></div>  <div class="pr-modal-footer">  <button type="button" onclick="closePrModal('mRejectModal')" style="padding:9px 22px;background:#6c757d;color:#fff;border:none;border-radius:6px;cursor:pointer;">Cancel</button>  <button type="button" id="mRejSubmitBtn" onclick="submitMerchReject()" style="padding:9px 22px;background:#dc3545;color:#fff;border:none;border-radius:6px;cursor:pointer;font-weight:600;">  <i class="fas fa-times"></i> Reject  </button>  </div>  </div>
</div>  <script>
// ── Tab switching ─────────────────────────────────────────────────────────────
function switchMainTab(tab, btn) {  document.getElementById('tab-fuel').style.display  = tab === 'fuel'  ? 'block' : 'none';  document.getElementById('tab-merch').style.display = tab === 'merch' ? 'block' : 'none';  document.querySelectorAll('.pr-tabs > .pr-tab').forEach(function(b) { b.classList.remove('active'); });  btn.classList.add('active');  if (tab === 'merch') loadMerchRequests();
}
function switchMerchTab(tab, btn) {  document.getElementById('merch-pending').style.display = tab === 'pending' ? 'block' : 'none';  document.getElementById('merch-history').style.display = tab === 'history' ? 'block' : 'none';  document.querySelectorAll('#tab-merch .pr-tabs .pr-tab').forEach(function(b) { b.classList.remove('active'); });  btn.classList.add('active');
}  // ── Modal helpers ─────────────────────────────────────────────────────────────
function openPrModal(id) { document.getElementById(id).classList.add('show'); document.body.style.overflow = 'hidden'; }
function closePrModal(id) { document.getElementById(id).classList.remove('show'); document.body.style.overflow = ''; }
document.querySelectorAll('.pr-modal').forEach(function(m) {  m.addEventListener('click', function(e) { if (e.target === this) closePrModal(this.id); });
});
document.addEventListener('keydown', function(e) {  if (e.key === 'Escape') document.querySelectorAll('.pr-modal.show').forEach(function(m) { closePrModal(m.id); });
});  // ── Fuel modal openers ────────────────────────────────────────────────────────
function openFuelApprove(id, fuel, liters) {  document.getElementById('fuelApproveId').value = id;  document.getElementById('fuelApproveFuel').textContent = fuel;  document.getElementById('fuelApproveLiters').value = '';  openPrModal('fuelApproveModal');  setTimeout(function() { document.getElementById('fuelApproveLiters').focus(); }, 100);
}
function openFuelReject(id, fuel) {  document.getElementById('fuelRejectId').value = id;  document.getElementById('fuelRejectFuel').textContent = fuel;  openPrModal('fuelRejectModal');
}  // ── Merchandise: load requests via AJAX ───────────────────────────────────────
var currentMerchId = null;  function loadMerchRequests() {  fetch('../backend/api/stock_request.php?action=get_requests')  .then(function(r) { return r.json(); })  .then(function(data) {  var requests = data.requests || [];  var pending  = requests.filter(function(r) { return r.status === 'Pending'; });  var history  = requests.filter(function(r) { return r.status !== 'Pending'; });  var forwarded = requests.filter(function(r) { return r.status === 'Forwarded to Admin'; });  document.getElementById('mTotal').textContent  = requests.length;  document.getElementById('mPending').textContent  = pending.length;  document.getElementById('mForwarded').textContent = forwarded.length;  document.getElementById('mRejected').textContent = requests.filter(function(r) { return r.status === 'Rejected'; }).length;  var badge = document.getElementById('merchPendingBadge');  if (pending.length > 0) { badge.textContent = pending.length; badge.style.display = 'inline'; }  else { badge.style.display = 'none'; }  var subBadge = document.getElementById('mPendingBadge');  if (pending.length > 0) { subBadge.textContent = pending.length; subBadge.style.display = 'inline'; }  else { subBadge.style.display = 'none'; }  renderMerchPending(pending);  renderMerchHistory(history);  })  .catch(function() {  document.getElementById('mPendingBody').innerHTML = '<tr><td colspan="10" style="text-align:center;padding:30px;color:#dc3545;">Error loading requests.</td></tr>';  });
}  function renderMerchPending(rows) {  var tbody = document.getElementById('mPendingBody');  if (rows.length === 0) {  tbody.innerHTML = '<tr><td colspan="10" style="text-align:center;padding:40px;color:#6c757d;"><i class="fas fa-check-circle" style="font-size:2em;display:block;margin-bottom:10px;color:#28a745;opacity:.5;"></i><strong>All caught up!</strong><br>No pending merchandise stock requests.</td></tr>';  return;  }  tbody.innerHTML = rows.map(function(r) {  var stockStatus = r.current_stock <= 0 ? 'OUT OF STOCK' : 'LOW STOCK';  var stockClr = r.current_stock <= 0 ? '#dc3545' : '#dc3545';  return '<tr>' +  '<td style="color:#6c757d;font-size:12px;">#' + r.id + '</td>' +  '<td style="font-size:12px;">' + fmtDate(r.created_at) + '</td>' +  '<td>' + esc(r.staff_name || '') + '</td>' +  '<td><code style="font-size:11px;">' + esc(r.item_sku || '') + '</code></td>' +  '<td><strong>' + esc(r.item_name) + '</strong></td>' +  '<td style="font-size:12px;">' + esc(r.item_category || '') + '</td>' +  '<td style="text-align:center;"><strong style="color:' + stockClr + ';">' + r.current_stock + '</strong><br><span style="font-size:10px;color:' + stockClr + ';font-weight:700;">' + stockStatus + '</span></td>' +  '<td style="font-size:12px;color:#6c757d;max-width:150px;">' + (r.remarks ? esc(r.remarks) : '<span style="color:#adb5bd;">—</span>') + '</td>' +  '<td style="text-align:center;font-size:11px;color:#6f42c1;font-weight:700;">Manager sets qty</td>' +  '<td style="white-space:nowrap;">' +  '<button class="pr-btn pr-btn-approve" onclick="openMerchApprove(' + r.id + ',\'' + esc(r.item_name) + '\',\'' + esc(r.item_sku||'') + '\',\'' + esc(r.item_category||'') + '\',' + r.current_stock + ',\'' + esc(r.staff_name||'') + '\')"><i class="fas fa-paper-plane"></i> Approve &amp; Forward</button> ' +  '<button class="pr-btn pr-btn-reject" onclick="openMerchReject(' + r.id + ',\'' + esc(r.item_name) + '\')"><i class="fas fa-times"></i> Reject</button>' +  '</td>' +  '</tr>';  }).join('');
}  function renderMerchHistory(rows) {  var tbody = document.getElementById('mHistoryBody');  if (rows.length === 0) {  tbody.innerHTML = '<tr><td colspan="9" style="text-align:center;padding:28px;color:#6c757d;">No processed requests yet.</td></tr>';  return;  }  tbody.innerHTML = rows.map(function(r) {  var st  = r.status || 'Unknown';  var cls = 'pr-sbadge pr-sbadge-' + st.toLowerCase().replace(/ /g,'-');  var qtyApproved = (r.approved_quantity !== null && r.approved_quantity !== undefined)  ? '<strong style="color:#28a745;font-size:14px;">' + r.approved_quantity + '</strong>'  : '<span style="color:#adb5bd;">—</span>';  var prId = r.purchase_request_id  ? '<span class="pr-id-badge">' + esc(r.purchase_request_id) + '</span>'  : '<span style="color:#adb5bd;">—</span>';  return '<tr>' +  '<td style="color:#6c757d;font-size:12px;">#' + r.id + '</td>' +  '<td style="font-size:12px;">' + fmtDate(r.created_at) + '</td>' +  '<td>' + esc(r.staff_name || '') + '</td>' +  '<td><strong>' + esc(r.item_name) + '</strong></td>' +  '<td style="text-align:center;">' + qtyApproved + '</td>' +  '<td><span class="' + cls + '">' + esc(st) + '</span></td>' +  '<td>' + prId + '</td>' +  '<td style="font-size:12px;color:#495057;max-width:180px;">' + (r.manager_notes ? esc(r.manager_notes) : '<span style="color:#adb5bd;">—</span>') + '</td>' +  '<td style="font-size:12px;color:#6c757d;">' + (r.processed_at ? fmtDate(r.processed_at) : fmtDate(r.updated_at || r.created_at)) + '</td>' +  '</tr>';  }).join('');
}  // ── Merchandise modal openers ─────────────────────────────────────────────────
function openMerchApprove(id, name, sku, category, curStock, staffName) {  currentMerchId = id;  document.getElementById('mAppSku').value  = sku;  document.getElementById('mAppName').value  = name;  document.getElementById('mAppCategory').value  = category;  document.getElementById('mAppStaff').value  = staffName;  document.getElementById('mAppCurStock').value  = curStock + ' units';  document.getElementById('mAppStockStatus').value = curStock <= 0 ? 'OUT OF STOCK' : 'LOW STOCK';  document.getElementById('mAppQty').value  = '';  document.getElementById('mAppNotes').value  = '';  document.getElementById('mAppError').style.display = 'none';  document.getElementById('mAppSubmitBtn').disabled = false;  document.getElementById('mAppSubmitBtn').innerHTML = '<i class="fas fa-paper-plane"></i> Approve &amp; Forward to Admin';  openPrModal('mApproveModal');  setTimeout(function() { document.getElementById('mAppQty').focus(); }, 100);
}
function openMerchReject(id, name) {  currentMerchId = id;  document.getElementById('mRejName').value  = name;  document.getElementById('mRejNotes').value = '';  document.getElementById('mRejError').style.display = 'none';  document.getElementById('mRejSubmitBtn').disabled = false;  document.getElementById('mRejSubmitBtn').innerHTML = '<i class="fas fa-times"></i> Reject';  openPrModal('mRejectModal');  setTimeout(function() { document.getElementById('mRejNotes').focus(); }, 100);
}  // ── Merchandise submit ────────────────────────────────────────────────────────
function submitMerchApprove() {  var qty  = parseInt(document.getElementById('mAppQty').value) || 0;  var notes = document.getElementById('mAppNotes').value.trim();  if (qty <= 0) { showMerchErr('mAppError', 'Please enter a valid approved quantity.'); return; }  var btn = document.getElementById('mAppSubmitBtn');  btn.disabled = true;  btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Processing...';  document.getElementById('mAppError').style.display = 'none';  fetch('../backend/api/stock_request.php?action=approve', {  method: 'POST',  headers: { 'Content-Type': 'application/json' },  body: JSON.stringify({ request_id: currentMerchId, approved_quantity: qty, manager_notes: notes })  })  .then(function(r) { return r.json(); })  .then(function(res) {  if (res.success) {  closePrModal('mApproveModal');  showAjaxFlash('success', '&#10003; Request #' + currentMerchId + ' approved &amp; forwarded to Admin.' + (res.purchase_request_id ? ' Purchase Request ID: <strong>' + res.purchase_request_id + '</strong>' : '') + (res.po_number ? ' PO: <strong>' + res.po_number + '</strong>' : ''));  loadMerchRequests();  } else {  showMerchErr('mAppError', res.message || 'Failed to approve.');  btn.disabled = false;  btn.innerHTML = '<i class="fas fa-paper-plane"></i> Approve &amp; Forward to Admin';  }  })  .catch(function() {  showMerchErr('mAppError', 'Network error. Please try again.');  btn.disabled = false;  btn.innerHTML = '<i class="fas fa-paper-plane"></i> Approve &amp; Forward to Admin';  });
}  function submitMerchReject() {  var notes = document.getElementById('mRejNotes').value.trim();  if (!notes) { showMerchErr('mRejError', 'Rejection reason is required.'); return; }  var btn = document.getElementById('mRejSubmitBtn');  btn.disabled = true;  btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Processing...';  document.getElementById('mRejError').style.display = 'none';  fetch('../backend/api/stock_request.php?action=reject', {  method: 'POST',  headers: { 'Content-Type': 'application/json' },  body: JSON.stringify({ request_id: currentMerchId, manager_notes: notes })  })  .then(function(r) { return r.json(); })  .then(function(res) {  if (res.success) {  closePrModal('mRejectModal');  showAjaxFlash('success', '&#10003; Request #' + currentMerchId + ' rejected.');  loadMerchRequests();  } else {  showMerchErr('mRejError', res.message || 'Failed to reject.');  btn.disabled = false;  btn.innerHTML = '<i class="fas fa-times"></i> Reject';  }  })  .catch(function() {  showMerchErr('mRejError', 'Network error. Please try again.');  btn.disabled = false;  btn.innerHTML = '<i class="fas fa-times"></i> Reject';  });
}  // ── Helpers ───────────────────────────────────────────────────────────────────
function showAjaxFlash(type, msg) {  var el = document.getElementById('ajaxFlash');  el.className = 'pr-alert-' + type;  el.innerHTML = '<i class="fas fa-' + (type === 'success' ? 'check-circle' : 'times-circle') + '"></i><span>' + msg + '</span>';  el.style.display = 'flex';  setTimeout(function() { el.style.display = 'none'; }, 7000);
}
function showMerchErr(id, msg) { var el = document.getElementById(id); el.textContent = msg; el.style.display = 'block'; }
function esc(str) { return String(str).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;'); }
function fmtDate(ds) {  if (!ds) return '—';  var d = new Date(ds);  return d.toLocaleDateString('en-PH', {month:'short',day:'numeric',year:'numeric'}) + ' ' +  d.toLocaleTimeString('en-PH', {hour:'2-digit',minute:'2-digit'});
}  document.addEventListener('DOMContentLoaded', function() {  ['mApproveModal','mRejectModal','fuelApproveModal','fuelRejectModal'].forEach(function(id) {  var el = document.getElementById(id);  if (el && el.parentNode !== document.body) document.body.appendChild(el);  });  <?php if ($active_tab === 'merch'): ?>  loadMerchRequests();  <?php endif; ?>
});
</script>  <?php include __DIR__ . '/../partials/footer.php'; ?>
